     1→/**
     2→ * FKSolicitudDesembolsoRequest - Solicitud de Desembolso contract request form for Operations department
     3→ * Specialized form with PDF upload, data extraction, and dynamic Anexo I table
     4→ */
     5→import React, { useState, useEffect } from 'react';
     6→import {
     7→  Box,
     8→  TextField,
     9→  Button,
    10→  Card,
    11→  CardContent,
    12→  Typography,
    13→  Alert,
    14→  CircularProgress,
    15→  Divider,
    16→  Table,
    17→  TableBody,
    18→  TableCell,
    19→  TableContainer,
    20→  TableHead,
    21→  TableRow,
    22→  IconButton,
    23→  Paper,
    24→  Stack,
    25→} from '@mui/material';
    26→import {
    27→  Search as SearchIcon,
    28→  UploadFile as UploadFileIcon,
    29→  Add as AddIcon,
    30→  Delete as DeleteIcon,
    31→  CheckCircle as CheckCircleIcon,
    32→} from '@mui/icons-material';
    33→import { legalService } from '../../services/legalService';
    34→import { operationsService } from '../../services/operationsService';
    35→import type { Client, ContractGeneration, AnexoItem, CotizacionData, SolicitudDesembolsoRequest } from '../../types/legal';
    36→
    37→const FKSolicitudDesembolsoRequest: React.FC = () => {
    38→  // Client search state
    39→  const [searchQuery, setSearchQuery] = useState('');
    40→  const [searching, setSearching] = useState(false);
    41→  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
    42→  const [searchResults, setSearchResults] = useState<Client[]>([]);
    43→
    44→  // Cotización PDF state
    45→  const [cotizacionFile, setCotizacionFile] = useState<File | null>(null);
    46→  const [extractedData, setExtractedData] = useState<CotizacionData | null>(null);
    47→  const [extracting, setExtracting] = useState(false);
    48→  const [fileError, setFileError] = useState<string | null>(null);
    49→
    50→  // Form state
    51→  const [numeroCotizacion, setNumeroCotizacion] = useState('');
    52→  const [fechaContrato, setFechaContrato] = useState('');
    53→  const [diasPlazo, setDiasPlazo] = useState(120);
    54→  const [anexoItems, setAnexoItems] = useState<AnexoItem[]>([]);
    55→  const [montoTotal, setMontoTotal] = useState(0);
    56→
    57→  // Submission state
    58→  const [requesting, setRequesting] = useState(false);
    59→  const [requestedContract, setRequestedContract] = useState<ContractGeneration | null>(null);
    60→  const [error, setError] = useState<string | null>(null);
    61→
    62→  // Calculate total when anexo items change
    63→  useEffect(() => {
    64→    const total = anexoItems.reduce((sum, item) => {
    65→      // Ensure monto is treated as a number (defensive check for string values)
    66→      const monto = typeof item.monto === 'string' ? parseFloat(item.monto) : Number(item.monto);
    67→      return sum + (monto || 0);
    68→    }, 0);
    69→    setMontoTotal(total);
    70→  }, [anexoItems]);
    71→
    72→  const handleSearch = async () => {
    73→    setSearching(true);
    74→    setError(null);
    75→    setSearchResults([]);
    76→    setSelectedClient(null);
    77→
    78→    try {
    79→      const results = await legalService.searchClients({ query: searchQuery.trim() || undefined });
    80→      setSearchResults(results);
    81→
    82→      if (results.length === 0) {
    83→        setError('No se encontraron clientes con ese criterio de búsqueda');
    84→      } else if (results.length === 1) {
    85→        setSelectedClient(results[0]);
    86→      }
    87→    } catch (err) {
    88→      setError('Error al buscar clientes. Por favor intente nuevamente.');
    89→      console.error('Search error:', err);
    90→    } finally {
    91→      setSearching(false);
    92→    }
    93→  };
    94→
    95→  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    96→    const file = event.target.files?.[0];
    97→    if (!file) return;
    98→
    99→    if (file.type !== 'application/pdf') {
   100→      setFileError('Solo se permiten archivos PDF');
   101→      setCotizacionFile(null);
   102→      return;
   103→    }
   104→
   105→    if (file.size > 5 * 1024 * 1024) {
   106→      setFileError('El archivo no debe superar 5MB');
   107→      setCotizacionFile(null);
   108→      return;
   109→    }
   110→
   111→    setCotizacionFile(file);
   112→    setFileError(null);
   113→    // Reset extracted data when new file is uploaded
   114→    setExtractedData(null);
   115→  };
   116→
   117→  const handleExtractData = async () => {
   118→    if (!cotizacionFile) {
   119→      setError('Debe seleccionar un archivo PDF primero');
   120→      return;
   121→    }
   122→
   123→    setExtracting(true);
   124→    setError(null);
   125→
   126→    try {
   127→      const data = await operationsService.parseCotizacionPdf(cotizacionFile);
   128→      setExtractedData(data);
   129→
   130→      // Pre-populate form fields
   131→      setNumeroCotizacion(data.numero_cotizacion || '');
   132→      setFechaContrato(data.fecha_contrato_credito || '');
   133→
   134→      // Convert monto from string to number for each anexo item
   135→      // Backend serializes Decimal as string, frontend needs numbers for calculations
   136→      const convertedItems = (data.anexo_items || []).map(item => ({
   137→        ...item,
   138→        monto: typeof item.monto === 'string' ? parseFloat(item.monto) : Number(item.monto)
   139→      }));
   140→      setAnexoItems(convertedItems);
   141→
   142→      setError(null);
   143→    } catch (err) {
   144→      const error = err as { response?: { data?: { detail?: string } }; message?: string };
   145→      setError(`Error al extraer datos del PDF: ${error.response?.data?.detail || error.message || 'Error desconocido'}`);
   146→      console.error('Extract error:', err);
   147→    } finally {
   148→      setExtracting(false);
   149→    }
   150→  };
   151→
   152→  const handleAddAnexoRow = () => {
   153→    setAnexoItems([...anexoItems, { acreedor: '', numero_instrumento: '', monto: 0 }]);
   154→  };
   155→
   156→  const handleRemoveAnexoRow = (index: number) => {
   157→    setAnexoItems(anexoItems.filter((_, i) => i !== index));
   158→  };
   159→
   160→  const handleAnexoItemChange = (index: number, field: keyof AnexoItem, value: string | number) => {
   161→    const updated = [...anexoItems];
   162→    updated[index] = { ...updated[index], [field]: value };
   163→    setAnexoItems(updated);
   164→  };
   165→
   166→  const handleSubmit = async () => {
   167→    if (!selectedClient) {
   168→      setError('Por favor seleccione un cliente');
   169→      return;
   170→    }
   171→
   172→    if (!numeroCotizacion) {
   173→      setError('Número de cotización es requerido');
   174→      return;
   175→    }
   176→
   177→    if (!fechaContrato) {
   178→      setError('Fecha de contrato de crédito es requerida');
   179→      return;
   180→    }
   181→
   182→    if (anexoItems.length === 0) {
   183→      setError('Debe agregar al menos un ítem en el Anexo I');
   184→      return;
   185→    }
   186→
   187→    if (montoTotal <= 0) {
   188→      setError('El monto total debe ser mayor a 0');
   189→      return;
   190→    }
   191→
   192→    setRequesting(true);
   193→    setError(null);
   194→
   195→    try {
   196→      const request: SolicitudDesembolsoRequest = {
   197→        client_nit: selectedClient.nit,
   198→        numero_cotizacion_desembolso: numeroCotizacion,
   199→        fecha_contrato_credito: fechaContrato,
   200→        monto: montoTotal,
   201→        dias_plazo: diasPlazo,
   202→        anexo_items: anexoItems,
   203→      };
   204→
   205→      const contract = await operationsService.generateSolicitudDesembolso(request);
   206→      setRequestedContract(contract);
   207→      setError(null);
   208→    } catch (err) {
   209→      const error = err as { response?: { data?: { detail?: string } }; message?: string };
   210→      setError(`Error al generar solicitud: ${error.response?.data?.detail || error.message || 'Error desconocido'}`);
   211→      console.error('Generation error:', err);
   212→    } finally {
   213→      setRequesting(false);
   214→    }
   215→  };
   216→
   217→  const handleReset = () => {
   218→    setSearchQuery('');
   219→    setSelectedClient(null);
   220→    setSearchResults([]);
   221→    setCotizacionFile(null);
   222→    setExtractedData(null);
   223→    setNumeroCotizacion('');
   224→    setFechaContrato('');
   225→    setDiasPlazo(120);
   226→    setAnexoItems([]);
   227→    setRequestedContract(null);
   228→    setError(null);
   229→    setFileError(null);
   230→  };
   231→
   232→  if (requestedContract) {
   233→    return (
   234→      <Card>
   235→        <CardContent>
   236→          <Box display="flex" alignItems="center" mb={2}>
   237→            <CheckCircleIcon color="success" sx={{ fontSize: 48, mr: 2 }} />
   238→            <Box>
   239→              <Typography variant="h6" gutterBottom>
   240→                Solicitud de Desembolso Generada Exitosamente
   241→              </Typography>
   242→              <Typography variant="body2" color="text.secondary">
   243→                La solicitud ha sido enviada al departamento Legal para revisión
   244→              </Typography>
   245→            </Box>
   246→          </Box>
   247→
   248→          <Divider sx={{ my: 2 }} />
   249→
   250→          <Stack spacing={2}>
   251→            <Box>
   252→              <Typography variant="subtitle2" color="text.secondary">ID de Contrato</Typography>
   253→              <Typography variant="body1" fontWeight="medium">{requestedContract.contract_id}</Typography>
   254→            </Box>
   255→            <Box>
   256→              <Typography variant="subtitle2" color="text.secondary">Cliente</Typography>
   257→              <Typography variant="body1">{selectedClient?.nombre_importador}</Typography>
   258→            </Box>
   259→            <Box>
   260→              <Typography variant="subtitle2" color="text.secondary">Número de Cotización</Typography>
   261→              <Typography variant="body1">{numeroCotizacion}</Typography>
   262→            </Box>
   263→            <Box>
   264→              <Typography variant="subtitle2" color="text.secondary">Monto Total</Typography>
   265→              <Typography variant="body1">${montoTotal.toLocaleString()} COP</Typography>
   266→            </Box>
   267→            <Box>
   268→              <Typography variant="subtitle2" color="text.secondary">Estado</Typography>
   269→              <Typography variant="body1" color="warning.main">En Revisión</Typography>
   270→            </Box>
   271→          </Stack>
   272→
   273→          <Box mt={3}>
   274→            <Button variant="contained" onClick={handleReset} fullWidth>
   275→              Generar Nueva Solicitud
   276→            </Button>
   277→          </Box>
   278→        </CardContent>
   279→      </Card>
   280→    );
   281→  }
   282→
   283→  return (
   284→    <Box>
   285→      <Typography variant="h6" gutterBottom>
   286→        Solicitud de Desembolso
   287→      </Typography>
   288→
   289→      {error && (
   290→        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
   291→          {error}
   292→        </Alert>
   293→      )}
   294→
   295→      {/* Section 1: Client Search */}
   296→      <Card sx={{ mb: 2 }}>
   297→        <CardContent>
   298→          <Typography variant="subtitle1" gutterBottom fontWeight="medium">
   299→            1. Seleccionar Cliente
   300→          </Typography>
   301→
   302→          <Stack direction="row" spacing={2} alignItems="center">
   303→            <TextField
   304→              fullWidth
   305→              label="Buscar por NIT o Nombre"
   306→              value={searchQuery}
   307→              onChange={(e) => setSearchQuery(e.target.value)}
   308→              onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
   309→              disabled={searching}
   310→              size="small"
   311→            />
   312→            <Button
   313→              variant="contained"
   314→              onClick={handleSearch}
   315→              disabled={searching || !searchQuery.trim()}
   316→              startIcon={searching ? <CircularProgress size={20} /> : <SearchIcon />}
   317→              sx={{ minWidth: 120 }}
   318→            >
   319→              Buscar
   320→            </Button>
   321→          </Stack>
   322→
   323→          {searchResults.length > 1 && (
   324→            <Box mt={2}>
   325→              <Typography variant="body2" color="text.secondary" gutterBottom>
   326→                Resultados de búsqueda:
   327→              </Typography>
   328→              {searchResults.map((client) => (
   329→                <Card
   330→                  key={client.id}
   331→                  variant="outlined"
   332→                  sx={{
   333→                    mb: 1,
   334→                    cursor: 'pointer',
   335→                    '&:hover': { bgcolor: 'action.hover' },
   336→                    bgcolor: selectedClient?.id === client.id ? 'action.selected' : 'inherit',
   337→                  }}
   338→                  onClick={() => setSelectedClient(client)}
   339→                >
   340→                  <CardContent sx={{ py: 1 }}>
   341→                    <Typography variant="body1" fontWeight="medium">
   342→                      {client.nombre_importador}
   343→                    </Typography>
   344→                    <Typography variant="body2" color="text.secondary">
   345→                      NIT: {client.nit} | {client.ciudad_domicilio}
   346→                    </Typography>
   347→                  </CardContent>
   348→                </Card>
   349→              ))}
   350→            </Box>
   351→          )}
   352→
   353→          {selectedClient && (
   354→            <Box mt={2} p={2} bgcolor="success.lighter" borderRadius={1}>
   355→              <Typography variant="body2" color="success.dark" fontWeight="medium">
   356→                Cliente seleccionado: {selectedClient.nombre_importador} (NIT: {selectedClient.nit})
   357→              </Typography>
   358→            </Box>
   359→          )}
   360→        </CardContent>
   361→      </Card>
   362→
   363→      {/* Section 2: Cotización Upload */}
   364→      <Card sx={{ mb: 2 }}>
   365→        <CardContent>
   366→          <Typography variant="subtitle1" gutterBottom fontWeight="medium">
   367→            2. Cargar Cotización PDF
   368→          </Typography>
   369→
   370→          <input
   371→            type="file"
   372→            accept="application/pdf"
   373→            onChange={handleFileChange}
   374→            style={{ display: 'none' }}
   375→            id="cotizacion-upload"
   376→          />
   377→          <label htmlFor="cotizacion-upload">
   378→            <Button variant="outlined" component="span" startIcon={<UploadFileIcon />} fullWidth>
   379→              {cotizacionFile ? cotizacionFile.name : 'Seleccionar Archivo PDF'}
   380→            </Button>
   381→          </label>
   382→
   383→          {fileError && (
   384→            <Alert severity="error" sx={{ mt: 1 }}>
   385→              {fileError}
   386→            </Alert>
   387→          )}
   388→
   389→          {cotizacionFile && !extractedData && (
   390→            <Box mt={2}>
   391→              <Button
   392→                variant="contained"
   393→                onClick={handleExtractData}
   394→                disabled={extracting}
   395→                startIcon={extracting ? <CircularProgress size={20} /> : <UploadFileIcon />}
   396→                fullWidth
   397→              >
   398→                {extracting ? 'Extrayendo Datos...' : 'Extraer Datos del PDF'}
   399→              </Button>
   400→            </Box>
   401→          )}
   402→
   403→          {extractedData && (
   404→            <Alert severity="success" sx={{ mt: 2 }}>
   405→              Datos extraídos exitosamente: {extractedData.anexo_items.length} ítems encontrados
   406→            </Alert>
   407→          )}
   408→        </CardContent>
   409→      </Card>
   410→
   411→      {/* Section 3: Extracted Data (Editable) */}
   412→      {extractedData && (
   413→        <Card sx={{ mb: 2 }}>
   414→          <CardContent>
   415→            <Typography variant="subtitle1" gutterBottom fontWeight="medium">
   416→              3. Datos de la Solicitud
   417→            </Typography>
   418→
   419→            <Stack spacing={2}>
   420→              <TextField
   421→                fullWidth
   422→                label="Número de Cotización de Desembolso"
   423→                value={numeroCotizacion}
   424→                onChange={(e) => setNumeroCotizacion(e.target.value)}
   425→                required
   426→                size="small"
   427→              />
   428→              <TextField
   429→                fullWidth
   430→                label="Fecha del Contrato de Crédito"
   431→                type="date"
   432→                value={fechaContrato}
   433→                onChange={(e) => setFechaContrato(e.target.value)}
   434→                InputLabelProps={{ shrink: true }}
   435→                required
   436→                size="small"
   437→              />
   438→              <TextField
   439→                fullWidth
   440→                label="Días de Plazo"
   441→                type="number"
   442→                value={diasPlazo}
   443→                onChange={(e) => setDiasPlazo(Number(e.target.value))}
   444→                inputProps={{ min: 30, max: 180 }}
   445→                required
   446→                size="small"
   447→              />
   448→              <TextField
   449→                fullWidth
   450→                label="Monto Total"
   451→                value={`$${montoTotal.toLocaleString()} COP`}
   452→                InputProps={{ readOnly: true }}
   453→                size="small"
   454→              />
   455→            </Stack>
   456→          </CardContent>
   457→        </Card>
   458→      )}
   459→
   460→      {/* Section 4: Anexo I Table */}
   461→      {extractedData && (
   462→        <Card sx={{ mb: 2 }}>
   463→          <CardContent>
   464→            <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
   465→              <Typography variant="subtitle1" fontWeight="medium">
   466→                4. Anexo I - Detalle de Pagos
   467→              </Typography>
   468→              <Button startIcon={<AddIcon />} onClick={handleAddAnexoRow} size="small">
   469→                Agregar Fila
   470→              </Button>
   471→            </Box>
   472→
   473→            <TableContainer component={Paper} variant="outlined">
   474→              <Table size="small">
   475→                <TableHead>
   476→                  <TableRow>
   477→                    <TableCell>Acreedor</TableCell>
   478→                    <TableCell>No. Instrumento</TableCell>
   479→                    <TableCell>Monto (COP)</TableCell>
   480→                    <TableCell width={60}>Acción</TableCell>
   481→                  </TableRow>
   482→                </TableHead>
   483→                <TableBody>
   484→                  {anexoItems.map((item, index) => (
   485→                    <TableRow key={index}>
   486→                      <TableCell>
   487→                        <TextField
   488→                          fullWidth
   489→                          value={item.acreedor}
   490→                          onChange={(e) => handleAnexoItemChange(index, 'acreedor', e.target.value)}
   491→                          size="small"
   492→                          variant="standard"
   493→                        />
   494→                      </TableCell>
   495→                      <TableCell>
   496→                        <TextField
   497→                          fullWidth
   498→                          value={item.numero_instrumento}
   499→                          onChange={(e) => handleAnexoItemChange(index, 'numero_instrumento', e.target.value)}
   500→                          size="small"
   501→                          variant="standard"
   502→                        />
   503→                      </TableCell>
   504→                      <TableCell>
   505→                        <TextField
   506→                          fullWidth
   507→                          type="number"
   508→                          value={item.monto}
   509→                          onChange={(e) => handleAnexoItemChange(index, 'monto', Number(e.target.value))}
   510→                          size="small"
   511→                          variant="standard"
   512→                        />
   513→                      </TableCell>
   514→                      <TableCell>
   515→                        <IconButton size="small" onClick={() => handleRemoveAnexoRow(index)} color="error">
   516→                          <DeleteIcon />
   517→                        </IconButton>
   518→                      </TableCell>
   519→                    </TableRow>
   520→                  ))}
   521→                  <TableRow>
   522→                    <TableCell colSpan={2} align="right">
   523→                      <strong>TOTAL:</strong>
   524→                    </TableCell>
   525→                    <TableCell colSpan={2}>
   526→                      <strong>${montoTotal.toLocaleString()} COP</strong>
   527→                    </TableCell>
   528→                  </TableRow>
   529→                </TableBody>
   530→              </Table>
   531→            </TableContainer>
   532→          </CardContent>
   533→        </Card>
   534→      )}
   535→
   536→      {/* Section 5: Submit */}
   537→      {extractedData && (
   538→        <Card>
   539→          <CardContent>
   540→            <Typography variant="subtitle1" gutterBottom fontWeight="medium">
   541→              5. Generar Solicitud
   542→            </Typography>
   543→
   544→            <Button
   545→              variant="contained"
   546→              color="primary"
   547→              onClick={handleSubmit}
   548→              disabled={requesting || !selectedClient || !numeroCotizacion || !fechaContrato || anexoItems.length === 0}
   549→              startIcon={requesting ? <CircularProgress size={20} /> : <CheckCircleIcon />}
   550→              fullWidth
   551→              size="large"
   552→            >
   553→              {requesting ? 'Generando...' : 'Solicitar Documento'}
   554→            </Button>
   555→          </CardContent>
   556→        </Card>
   557→      )}
   558→    </Box>
   559→  );
   560→};
   561→
   562→export default FKSolicitudDesembolsoRequest;
